Lemma mid_facts fxi Ri Mi mdi cri si smi ei Y :
  mid fxi Ri Mi mdi cri si smi ei Y ->
  (getr Ri (PMK.reg 2) = Z_to_bv 64 (sp - 64) /\ getr Ri (PMK.reg 8) = Z_to_bv 64 (fb + 40) /\ getr Ri (PMK.reg 9) = Z_to_bv 64 (fb + 8)
   /\ getr Ri (PMK.reg 18) = Z_to_bv 64 (fb + 40 + 24))
  /\ (L5.writable RSEGS Mi (sp - 64) 64 /\ L5.writable RSEGS Mi (fb + 40 + 8) 1 /\ L5.img_clear Mi 65536 765992 /\ L5.defined Mi (sp - 64) 64)
  /\ (m_halted mdi = None /\ m_vm_lazy mdi = [])
  /\ (L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
      /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
